package com.bookstore.security; import com.bookstore.entity.User; import com.bookstore.repository.UserRepository; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service public class CustomUserDetailsService implements UserDetailsService {private final UserRepository repo; public CustomUserDetailsService(UserRepository r){repo=r;} public UserDetails loadUserByUsername(String u){User x=repo.findByUsername(u).orElseThrow(()->new UsernameNotFoundException(u)); return User.withUsername(x.getUsername()).password(x.getPassword()).roles(x.getRole().name()).build();}}
